def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    bars=[]
    for r,row in enumerate(grid):
        for c in range(w-2):
            if row[c]==row[c+1]==row[c+2] and row[c] not in (1,): bars.append((r,c,row[c]))
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (1,3)]
    if not pts: return out
    r0,c0,color=pts[0]
    # vertical rays at point coordinate, toward each edge
    for r in range(r0-1,-1,-1): out[r][c0]=color
    out[r0][c0]=4
    for r in range(r0+1,h): out[r][c0]=color
    # project the three cells of the lower marker bar inward
    for r,c,v in bars:
        if r==h-1:
            for x in range(c,c+3):
                for y in range(h-2,-1,-1):
                    if (y,x)==(r0,c0): break
                    out[y][x]=color
    return out
